"""Launch move_group and supporting nodes for the simple_arm MoveIt 2 setup."""

from pathlib import Path

import yaml
from ament_index_python.packages import get_package_share_directory
from launch import LaunchDescription
from launch_ros.actions import Node


def load_file(path: Path) -> str:
    return path.read_text()


def load_yaml(path: Path):
    with open(path, "r") as f:
        return yaml.safe_load(f)


def generate_launch_description():
    pkg_dir = Path(__file__).resolve().parent.parent
    config_dir = pkg_dir / "config"

    robot_description = {"robot_description": load_file(pkg_dir / "urdf" / "arm.urdf")}
    robot_description_semantic = {
        "robot_description_semantic": load_file(pkg_dir / "srdf" / "arm.srdf")
    }

    kinematics_yaml = load_yaml(config_dir / "kinematics.yaml")
    joint_limits_yaml = load_yaml(config_dir / "joint_limits.yaml")

    ompl_yaml = load_yaml(config_dir / "ompl_planning.yaml")
    ompl_defaults_path = (
        Path(get_package_share_directory("moveit_configs_utils"))
        / "default_configs"
        / "ompl_defaults.yaml"
    )
    ompl_config = dict(ompl_yaml)
    ompl_config.update(load_yaml(ompl_defaults_path))

    planning_pipeline_config = {
        "planning_pipelines": ["ompl"],
        "default_planning_pipeline": "ompl",
        "ompl": ompl_config,
    }

    moveit_controllers_yaml = load_yaml(config_dir / "moveit_controllers.yaml")
    trajectory_execution = {
        "moveit_manage_controllers": True,
        "trajectory_execution.allowed_execution_duration_scaling": 1.2,
        "trajectory_execution.allowed_goal_duration_margin": 0.5,
        "trajectory_execution.allowed_start_tolerance": 0.01,
    }
    trajectory_execution.update(moveit_controllers_yaml)

    planning_scene_monitor_parameters = {
        "publish_planning_scene": True,
        "publish_geometry_updates": True,
        "publish_state_updates": True,
        "publish_transforms_updates": True,
    }

    move_group_node = Node(
        package="moveit_ros_move_group",
        executable="move_group",
        output="screen",
        parameters=[
            robot_description,
            robot_description_semantic,
            {"robot_description_kinematics": kinematics_yaml},
            {"robot_description_planning": joint_limits_yaml},
            planning_pipeline_config,
            trajectory_execution,
            planning_scene_monitor_parameters,
            {"use_sim_time": False},
        ],
    )

    robot_state_publisher_node = Node(
        package="robot_state_publisher",
        executable="robot_state_publisher",
        output="screen",
        parameters=[robot_description],
    )

    ros2_control_node = Node(
        package="controller_manager",
        executable="ros2_control_node",
        output="screen",
        parameters=[robot_description, str(config_dir / "ros2_controllers.yaml")],
    )

    joint_state_broadcaster_spawner = Node(
        package="controller_manager",
        executable="spawner",
        arguments=["joint_state_broadcaster"],
        output="screen",
    )

    arm_controller_spawner = Node(
        package="controller_manager",
        executable="spawner",
        arguments=["arm_controller"],
        output="screen",
    )

    return LaunchDescription(
        [
            robot_state_publisher_node,
            ros2_control_node,
            joint_state_broadcaster_spawner,
            arm_controller_spawner,
            move_group_node,
        ]
    )

